-- What supabase/announce.sql does, tried inside the rolled-back transaction
-- of a dry run: nothing here is kept. Made-up accounts, made and gone with
-- the transaction: Ada, Bo and Cy at Resend's test addresses (the checks'
-- pool), Dee and Eve at example.com (anybody else). Ada is a beta tester,
-- has a model shared and Pro in test billing; Cy signed up a month ago; Dee
-- and Ada ask for news by email, Eve never said. Only the made-up five are
-- named in what is printed; anybody else is only counted.
--
--   set -a; . ./.env; set +a
--   PG_MODULE=/tmp/pg/node_modules/pg/lib/index.js \
--     node tools/apply_sql.mjs supabase/announce.sql --dry --try=tools/announce_try.sql --table=announcements
--
-- Each statement is on one line: the dry run splits at a semicolon that
-- ends a line. Inside one transaction now() never moves; each read is its
-- own statement, since a stable function sees the rows as its statement began.
create function pg_temp.tries(statement text) returns text language plpgsql as $$ begin execute statement; return 'allowed'; exception when others then return 'refused: ' || sqlerrm; end $$;
grant execute on function pg_temp.tries(text) to anon, authenticated;
create function pg_temp.who(account uuid) returns text language sql as $$ select case account when '00000000-0000-4000-8000-0000000aa001' then 'ada' when '00000000-0000-4000-8000-0000000aa002' then 'bo' when '00000000-0000-4000-8000-0000000aa003' then 'cy' when '00000000-0000-4000-8000-0000000aa004' then 'dee' when '00000000-0000-4000-8000-0000000aa005' then 'eve' end $$;
-- Nothing there before: the five tables are new and empty, and no notice had an end.
select (select count(*) from public.announcements) as announcements, (select count(*) from public.announcement_reads) as reads, (select count(*) from public.announcement_mails) as mails, (select count(*) from public.news_mail) as news, (select count(*) from public.site_notice_hides) as hides, (select count(*) from public.site_notices where ends_at is not null) as notices_ending;
-- Row security on, no policy, no grant to any role, the server's included.
select c.relname, c.relrowsecurity as row_security, (select count(*) from pg_policies p where p.tablename = c.relname) as policies, has_table_privilege('anon', c.oid, 'select') as anon_reads, has_table_privilege('authenticated', c.oid, 'select') as signed_in_reads, has_table_privilege('service_role', c.oid, 'select') as server_reads from pg_class c where c.relnamespace = 'public'::regnamespace and c.relname in ('announcements', 'announcement_reads', 'announcement_mails', 'news_mail', 'site_notice_hides') order by c.relname;
-- The functions: the server's alone, each security definer.
select p.proname, has_function_privilege('anon', p.oid, 'execute') as anon, has_function_privilege('authenticated', p.oid, 'execute') as signed_in, has_function_privilege('service_role', p.oid, 'execute') as server, p.prosecdef as security_definer from pg_proc p where p.pronamespace = 'public'::regnamespace and (p.proname like 'announce%' or p.proname in ('notification_rows', 'news_choice', 'site_notice', 'site_notices_list', 'site_notice_ends', 'site_notice_hide', 'site_notice_hidden')) order by p.proname;
-- The made-up five.
insert into auth.users (id, instance_id, aud, role, email, created_at, email_confirmed_at) values ('00000000-0000-4000-8000-0000000aa001', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'an-try-ada@resend.dev', now(), now()), ('00000000-0000-4000-8000-0000000aa002', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'an-try-bo@resend.dev', now(), now()), ('00000000-0000-4000-8000-0000000aa003', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'an-try-cy@resend.dev', now() - interval '30 days', now() - interval '30 days'), ('00000000-0000-4000-8000-0000000aa004', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'an-try-dee@example.com', now(), now()), ('00000000-0000-4000-8000-0000000aa005', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'an-try-eve@example.com', now(), now());
select public.answer_age('00000000-0000-4000-8000-0000000aa001', true)->>'over_13' as ada, public.answer_age('00000000-0000-4000-8000-0000000aa002', true)->>'over_13' as bo, public.answer_age('00000000-0000-4000-8000-0000000aa004', true)->>'over_13' as dee;
insert into public.people (account, handle, name) values ('00000000-0000-4000-8000-0000000aa001', 'an-try-ada', 'Ada Try'), ('00000000-0000-4000-8000-0000000aa002', 'an-try-bo', 'Bo Try'), ('00000000-0000-4000-8000-0000000aa004', 'an-try-dee', 'Dee Try');
insert into public.beta_testers (account, state, joined_at, terms, via) values ('00000000-0000-4000-8000-0000000aa001', 'tester', now(), '2026-11-01', 'site');
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, listed_at, test, created_at, has_image) values ('AnTry00001', '00000000-0000-4000-8000-0000000aa001', 'Try tower', 'Ada Try', 12, 100, true, now(), true, now(), false);
insert into public.admission_snapshots (key, value) values ('admission:v2:brickworks:test:c:00000000-0000-4000-8000-0000000aa001', '{"value":{"plan":{"key":"pro","name":"Pro","source":"override"}}}');
select public.news_choice('00000000-0000-4000-8000-0000000aa001', true) as ada_news, public.news_choice('00000000-0000-4000-8000-0000000aa004', true) as dee_news, public.news_choice('00000000-0000-4000-8000-0000000aa005') as eve_never_said, public.news_choice('00000000-0000-4000-8000-000000000000', true) as nobody;
-- Who each audience reaches, of the made-up five: a test one only the checks' pool, any other only the others.
select k.kind, array(select pg_temp.who(a) from public.announce_audience(k.aud, k.test) a where pg_temp.who(a) is not null order by 1) as reaches from (values ('everyone, test', '{"kind":"everyone"}'::jsonb, true), ('everyone', '{"kind":"everyone"}'::jsonb, false), ('beta, test', '{"kind":"beta"}'::jsonb, true), ('since now, test', jsonb_build_object('kind', 'since', 'since', now()), true), ('since now', jsonb_build_object('kind', 'since', 'since', now()), false), ('published, test', '{"kind":"published"}'::jsonb, true), ('person AN-TRY-ADA, test', '{"kind":"person","handle":"AN-TRY-ADA"}'::jsonb, true), ('person an-try-dee, test', '{"kind":"person","handle":"an-try-dee"}'::jsonb, true), ('person an-try-dee', '{"kind":"person","handle":"an-try-dee"}'::jsonb, false), ('plan pro (test billing), test', '{"kind":"plan","plan":"pro","mode":"test"}'::jsonb, true), ('plan free, the default, test', '{"kind":"plan","plan":"free","mode":"test","default":true}'::jsonb, true), ('plan pro (live billing), test', '{"kind":"plan","plan":"pro","mode":"live"}'::jsonb, true), ('since not a date, test', '{"kind":"since","since":"soon"}'::jsonb, true), ('no such kind, test', '{"kind":"nobody"}'::jsonb, true)) k(kind, aud, test);
-- Counted: everyone is every account of its pool; with how many of them asked for news by email (a test one mails nobody).
select (public.announce_count('{"kind":"everyone"}', true)->>'count')::bigint = (select count(*) from auth.users where coalesce(email, '') ~* '@resend\.dev$') as test_everyone_is_every_test_account, (public.announce_count('{"kind":"everyone"}', false)->>'count')::bigint = (select count(*) from auth.users where coalesce(email, '') !~* '@resend\.dev$') as everyone_is_every_other_account, public.announce_count('{"kind":"person","handle":"an-try-dee"}', false) as dee, public.announce_count('{"kind":"person","handle":"an-try-ada"}', true) as ada_test;
-- The table refuses what the API refuses too: a link that is not this site's or https, a title too long, a send without a press.
select pg_temp.tries($q$select public.announce_keep(null, true, 'x', '', 'http://example.com/', '{"kind":"everyone"}', false, 'dry-run')$q$) as http_link, pg_temp.tries($q$select public.announce_keep(null, true, 'x', '', '//evil.example/', '{"kind":"everyone"}', false, 'dry-run')$q$) as protocol_relative, pg_temp.tries($q$select public.announce_keep(null, true, repeat('x', 121), '', null, '{"kind":"everyone"}', false, 'dry-run')$q$) as long_title, pg_temp.tries($q$select public.announce_keep(null, true, 'x', '', null, '{"kind":"anyone"}', false, 'dry-run')$q$) as bad_audience, pg_temp.tries($q$insert into public.announcements (title, audience, status, sent_at, recipients, reach, made_by) values ('t', '{"kind":"everyone"}', 'sent', now(), '{}', 0, 'dry-run')$q$) as sent_without_press;
-- One for those signed up since now: Ada and Bo, not Cy. Kept as a draft, then pressed with the page's hash.
create temporary table t_one on commit drop as select public.announce_keep(null, true, 'Try: the studio is faster', 'Words of the try.', '/gallery', jsonb_build_object('kind', 'since', 'since', now()), true, 'dry-run')->'announcement' as a;
select a->>'status' as status, a->>'link' as link, a->>'email' as email from t_one;
create temporary table t_press on commit drop as select public.announce_press((a->>'id')::bigint, true, (a->>'changed_at')::timestamptz, 'dry-run', repeat('a', 64), null, 3) as r from t_one;
select r->'refused' as refused, r->'announcement'->>'status' as status, r->'announcement'->>'pressed_by' as pressed_by, (r->'announcement'->>'reach')::integer >= 2 as reach_counted from t_press;
select public.announce_one((a->>'id')::bigint, true)->>'status' as one_reads_it, public.announce_one((a->>'id')::bigint, false) is null as not_in_the_other_pool, public.announce_one((a->>'id')::bigint, true) ? 'recipients' as one_lists_who from t_one;
select array(select pg_temp.who(x) from unnest(n.recipients) x where pg_temp.who(x) is not null order by 1) as sent_to, n.reach = cardinality(n.recipients) as reach_is_who from public.announcements n where n.id = (select (a->>'id')::bigint from t_one);
-- A test one mails nobody, though Ada asked for news by email.
select public.announce_mail_take((a->>'id')::bigint, 100) as test_one_takes, (select count(*) from jsonb_array_elements(public.announce_mail_due()) d where d::text::bigint = (a->>'id')::bigint) as test_one_due_to_mail from t_one;
-- Two presses make one send: the same press again (another tab), and the press after it, are refused.
select public.announce_press((a->>'id')::bigint, true, (a->>'changed_at')::timestamptz, 'dry-run', repeat('a', 64), null, 3)->'refused' as pressed_again from t_one;
select public.announce_keep((a->>'id')::bigint, true, 'Changed after', '', null, '{"kind":"everyone"}', false, 'dry-run')->'refused' as kept_after_sent from t_one;
-- In Ada's and Bo's notifications, through notification_list as the page asks it; not Cy's, nor Dee's.
select pg_temp.who(v.account) as who, (select jsonb_agg(jsonb_build_object('title', r->>'title', 'said', r->>'said', 'link', r->>'link', 'read', r->'read', 'edited', r->'edited')) from jsonb_array_elements(public.notification_list(v.account, false)->'rows') r where r->>'kind' = 'announcement') as told, (public.notification_counts(v.account)->>'notifications')::integer as counted_new from (values ('00000000-0000-4000-8000-0000000aa001'::uuid), ('00000000-0000-4000-8000-0000000aa002'::uuid), ('00000000-0000-4000-8000-0000000aa003'::uuid), ('00000000-0000-4000-8000-0000000aa004'::uuid)) v(account);
-- Opened by Ada, its link followed by Bo; Cy may not mark one not sent to her. Bo opens Notifications: seen.
select public.announcement_read('00000000-0000-4000-8000-0000000aa001', (a->>'id')::bigint, false) as ada_opened, public.announcement_read('00000000-0000-4000-8000-0000000aa002', (a->>'id')::bigint, true) as bo_clicked, public.announcement_read('00000000-0000-4000-8000-0000000aa003', (a->>'id')::bigint, false) as cy_refused, public.announcement_read(null, (a->>'id')::bigint, false) as nobody from t_one;
select public.notification_list('00000000-0000-4000-8000-0000000aa002', true) is not null as bo_opened_notifications;
select (select r->'read' from jsonb_array_elements(public.notification_list('00000000-0000-4000-8000-0000000aa001', false)->'rows') r where r->>'kind' = 'announcement') as ada_reads_it_read, (public.notification_counts('00000000-0000-4000-8000-0000000aa002')->>'notifications')::integer as bo_new_after_opening;
select l->>'title' as title, l->'reach' as reach_of_made_up_since_now, l->'seen' as seen, l->'read' as read, l->'clicked' as clicked, l->'mails' as mails from jsonb_array_elements(public.announce_list(true, 10)) l where (l->>'id')::bigint = (select (a->>'id')::bigint from t_one);
-- Edited: its new words, marked edited; refused on words changed since the page read them.
select public.announce_edit((a->>'id')::bigint, true, (a->>'changed_at')::timestamptz, 'Stale', '', null)->'refused' as stale_edit from t_one;
select public.announce_edit((a->>'id')::bigint, true, (select n.changed_at from public.announcements n where n.id = (a->>'id')::bigint), 'Try: the studio is faster still', 'Edited words.', '/gallery?sort=new')->'announcement'->>'edited_at' is not null as edited from t_one;
select (select jsonb_build_object('title', r->>'title', 'said', r->>'said', 'link', r->>'link', 'edited', r->'edited') from jsonb_array_elements(public.notification_list('00000000-0000-4000-8000-0000000aa001', false)->'rows') r where r->>'kind' = 'announcement') as ada_sees;
-- Scheduled for an hour from now; edited, it is a draft again with its press forgotten; scheduled again, it is due once its time comes, and goes only with the hash it was pressed on.
create temporary table t_two on commit drop as select public.announce_keep(null, true, 'Try: scheduled', 'Later.', null, '{"kind":"person","handle":"an-try-ada"}', false, 'dry-run')->'announcement' as a;
select public.announce_press((a->>'id')::bigint, true, (a->>'changed_at')::timestamptz, 'dry-run', repeat('b', 64), now() + interval '1 hour', 3)->'announcement'->>'status' as scheduled from t_two;
select public.announce_keep((a->>'id')::bigint, true, 'Try: scheduled, changed', 'Later still.', null, '{"kind":"person","handle":"an-try-ada"}', false, 'dry-run') - 'announcement' as kept from t_two;
select n.status || ', ' || coalesce(n.pressed_hash, 'no press') as now_is from public.announcements n where n.id = (select (a->>'id')::bigint from t_two);
select public.announce_press((a->>'id')::bigint, true, (select n.changed_at from public.announcements n where n.id = (a->>'id')::bigint), 'dry-run', repeat('c', 64), now() + interval '1 hour', 3)->'announcement'->>'status' as scheduled_again, (select count(*) from jsonb_array_elements(public.announce_due()) d where (d->>'id')::bigint = (a->>'id')::bigint) as due_before_its_time from t_two;
update public.announcements set send_at = now() - interval '1 minute' where id = (select (a->>'id')::bigint from t_two);
select (select count(*) from jsonb_array_elements(public.announce_due()) d where (d->>'id')::bigint = (a->>'id')::bigint) as due_at_its_time, public.announce_press((a->>'id')::bigint, true, (select n.changed_at from public.announcements n where n.id = (a->>'id')::bigint), 'cron', repeat('d', 64), null, 3)->'refused' as other_words from t_two;
select public.announce_press((a->>'id')::bigint, true, (select n.changed_at from public.announcements n where n.id = (a->>'id')::bigint), 'cron', repeat('c', 64), null, 3)->'announcement'->>'status' as sent_as_pressed, (select n.pressed_by from public.announcements n where n.id = (a->>'id')::bigint) as pressed_by from t_two;
-- The day's limit: two sent today of at most two, a third refused, now or scheduled for today.
create temporary table t_three on commit drop as select public.announce_keep(null, true, 'Try: one too many', '', null, '{"kind":"person","handle":"an-try-ada"}', false, 'dry-run')->'announcement' as a;
select public.announce_press((a->>'id')::bigint, true, (a->>'changed_at')::timestamptz, 'dry-run', repeat('e', 64), null, 2) as now_over, public.announce_press((a->>'id')::bigint, true, (a->>'changed_at')::timestamptz, 'dry-run', repeat('e', 64), date_trunc('day', now() at time zone 'utc') at time zone 'utc' + interval '23 hours 59 minutes', 2)->'refused' as later_today_over from t_three;
select public.announce_press((a->>'id')::bigint, true, (a->>'changed_at')::timestamptz, 'dry-run', repeat('e', 64), now() + interval '2 days', 2)->'announcement'->>'status' as another_day from t_three;
select public.announce_unschedule((a->>'id')::bigint, true)->'announcement'->>'status' as unscheduled, public.announce_unschedule((a->>'id')::bigint, true)->'refused' as unscheduled_again, public.announce_drop((a->>'id')::bigint, true) as dropped, public.announce_drop((a->>'id')::bigint, true)->'refused' as dropped_again from t_three;
-- Withdrawn: gone from Ada's notifications and its count; she can no longer mark it; it cannot be withdrawn twice.
select public.announce_withdraw((a->>'id')::bigint, true, 'dry-run')->'announcement'->>'status' as withdrawn, public.announce_withdraw((a->>'id')::bigint, true, 'dry-run')->'refused' as withdrawn_again from t_one;
select (select count(*) from jsonb_array_elements(public.notification_list('00000000-0000-4000-8000-0000000aa001', false)->'rows') r where (r->>'announcement')::bigint = (a->>'id')::bigint) as ada_still_told, public.announcement_read('00000000-0000-4000-8000-0000000aa001', (a->>'id')::bigint, true)->'refused' as ada_marks from t_one;
-- Mail: one to Dee, who asked, mails her once, and only once however often it is taken.
create temporary table t_dee on commit drop as select public.announce_keep(null, false, 'Try: news for Dee', 'Mailed.', 'https://brickworks.diy/gallery', '{"kind":"person","handle":"an-try-dee"}', true, 'dry-run')->'announcement' as a;
select public.announce_press((a->>'id')::bigint, false, (a->>'changed_at')::timestamptz, 'dry-run', repeat('f', 64), null, 3)->'announcement'->>'reach' as reach from t_dee;
select (select count(*) from jsonb_array_elements(public.announce_mail_due()) d where d::text::bigint = (a->>'id')::bigint) as due_to_mail, (select jsonb_agg(pg_temp.who((m->>'account')::uuid)) from jsonb_array_elements(public.announce_mail_take((a->>'id')::bigint, 100)) m) as first_take from t_dee;
select public.announce_mail_take((a->>'id')::bigint, 100) as second_take, public.announce_mail_done((a->>'id')::bigint, '[{"account":"00000000-0000-4000-8000-0000000aa004","state":"sent","sent_id":"re_dry_run"}]') as done, (select count(*) from jsonb_array_elements(public.announce_mail_due()) d where d::text::bigint = (a->>'id')::bigint) as due_after from t_dee;
select l->'mails' as mails from jsonb_array_elements(public.announce_list(false, 50)) l where (l->>'id')::bigint = (select (a->>'id')::bigint from t_dee);
-- A batch Resend refused before taking any (too many at once): taken again by the next round, once.
update public.announcement_mails set state = 'sending', sent_id = null where announcement = (select (a->>'id')::bigint from t_dee);
select public.announce_mail_done((a->>'id')::bigint, '[{"account":"00000000-0000-4000-8000-0000000aa004","state":"again"}]') as released, (select jsonb_agg(pg_temp.who((m->>'account')::uuid)) from jsonb_array_elements(public.announce_mail_take((a->>'id')::bigint, 100)) m) as taken_again from t_dee;
select public.announce_mail_done((a->>'id')::bigint, '[{"account":"00000000-0000-4000-8000-0000000aa004","state":"sent","sent_id":"re_dry_run_2"}]') as done_again, public.announce_mail_done((a->>'id')::bigint, '[{"account":"00000000-0000-4000-8000-0000000aa004","state":"again"}]') as sent_is_not_released from t_dee;
-- Dee unsubscribes from a mail: the next one to her is not mailed.
select public.news_choice('00000000-0000-4000-8000-0000000aa004', false, 'unsubscribe') as dee_unsubscribed;
select n.via, n.news from public.news_mail n where n.account = '00000000-0000-4000-8000-0000000aa004';
create temporary table t_dee2 on commit drop as select public.announce_keep(null, false, 'Try: more news for Dee', 'Not mailed.', null, '{"kind":"person","handle":"an-try-dee"}', true, 'dry-run')->'announcement' as a;
select public.announce_press((a->>'id')::bigint, false, (a->>'changed_at')::timestamptz, 'dry-run', repeat('0', 64), null, 3)->'announcement'->>'reach' as reach, public.announce_mail_take((a->>'id')::bigint, 100) as takes from t_dee2;
-- The notice: an end, past ends refused, it goes by itself at its end; hidden by Ada, for Ada alone.
create temporary table t_notice on commit drop as select (public.site_notice_set('announce-try', '{"en":"Try notice."}'::jsonb, 'warn', 'dry-run')->'notice'->>'id')::bigint as id;
select public.site_notice_ends('announce-try', id, now() + interval '1 hour') is not null as ends_set, public.site_notice_ends('announce-try', id, now() - interval '1 minute') as past, public.site_notice_ends('live', id, now() + interval '1 hour') as other_scope from t_notice;
select public.site_notice('announce-try')->>'ends_at' is not null as shows_its_end;
select public.site_notice_hide('00000000-0000-4000-8000-0000000aa001', id) as ada_hides, public.site_notice_hide('00000000-0000-4000-8000-0000000aa001', id) as again, public.site_notice_hide(null, id) as nobody from t_notice;
select public.site_notice_hidden('00000000-0000-4000-8000-0000000aa001', id) as hidden_for_ada, public.site_notice_hidden('00000000-0000-4000-8000-0000000aa002', id) as hidden_for_bo from t_notice;
update public.site_notices set ends_at = now() - interval '1 second' where id = (select id from t_notice);
select public.site_notice('announce-try') is null as gone_at_its_end, (select l->>'ends_at' is not null from jsonb_array_elements(public.site_notices_list('announce-try', 5)) l limit 1) as history_says_its_end;
-- Nobody but the server runs any of it.
select pg_temp.tries($q$set local role anon; select public.announce_list(true, 5)$q$) as anon_lists, pg_temp.tries($q$set local role authenticated; select public.news_choice('00000000-0000-4000-8000-0000000aa001', false)$q$) as signed_in_chooses;
